-- Idempotent seed: counties, sub-counties, LCT source, Mfanisi Go provider panel
-- Safe to re-run via: npx prisma db execute --file prisma/seed-healthcare-providers.sql

-- Counties (stable ids 1-47)

-- Sub-counties

-- Provider source

-- Healthcare providers (subCountyId intentionally NULL for LCT panel)
DO $$
DECLARE
  source_id INT;
  pkg_id INT;
BEGIN
  SELECT id INTO source_id FROM "provider_sources" WHERE "code" = 'lct-africa';
  SELECT id INTO pkg_id FROM "packages" WHERE "slug" = 'mfanisi-go' LIMIT 1;


  IF pkg_id IS NOT NULL THEN
    SELECT pkg_id, hp.id, true, CURRENT_TIMESTAMP, 'seed'
    FROM "healthcare_providers" hp
    WHERE hp."sourceId" = source_id AND hp."isActive" = true
    ON CONFLICT ("packageId", "healthcareProviderId") DO UPDATE SET "isActive" = true;
  END IF;
END $$;

